/**
 * @suppress
 */
public object FfiConverterTypeMobileCoreController: FfiConverter<MobileCoreController, Pointer> {

    override fun lower(value: MobileCoreController): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): MobileCoreController {
        return MobileCoreController(value)
    }

    override fun read(buf: ByteBuffer): MobileCoreController {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: MobileCoreController) = 8UL

    override fun write(value: MobileCoreController, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



