sealed class MobileBlobTransferState {
    
    object Available : MobileBlobTransferState()
    
    
    data class Downloading(
        val `receivedChunks`: kotlin.UInt, 
        val `totalChunks`: kotlin.UInt) : MobileBlobTransferState() {
        companion object
    }
    
    data class Completed(
        val `savedPath`: kotlin.String?) : MobileBlobTransferState() {
        companion object
    }
    
    data class Failed(
        val `reason`: kotlin.String) : MobileBlobTransferState() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileBlobTransferState : FfiConverterRustBuffer<MobileBlobTransferState>{
    override fun read(buf: ByteBuffer): MobileBlobTransferState {
        return when(buf.getInt()) {
            1 -> MobileBlobTransferState.Available
            2 -> MobileBlobTransferState.Downloading(
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> MobileBlobTransferState.Completed(
                FfiConverterOptionalString.read(buf),
                )
            4 -> MobileBlobTransferState.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileBlobTransferState) = when(value) {
        is MobileBlobTransferState.Available -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is MobileBlobTransferState.Downloading -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`receivedChunks`)
                + FfiConverterUInt.allocationSize(value.`totalChunks`)
            )
        }
        is MobileBlobTransferState.Completed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`savedPath`)
            )
        }
        is MobileBlobTransferState.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: MobileBlobTransferState, buf: ByteBuffer) {
        when(value) {
            is MobileBlobTransferState.Available -> {
                buf.putInt(1)
                Unit
            }
            is MobileBlobTransferState.Downloading -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`receivedChunks`, buf)
                FfiConverterUInt.write(value.`totalChunks`, buf)
                Unit
            }
            is MobileBlobTransferState.Completed -> {
                buf.putInt(3)
                FfiConverterOptionalString.write(value.`savedPath`, buf)
                Unit
            }
            is MobileBlobTransferState.Failed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





