                FfiConverterString.read(buf),
                )
            2 -> MobileChatContent.InlineImage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterOptionalByteArray.read(buf),
                FfiConverterTypeMobileBlobTransferState.read(buf),
                )
            3 -> MobileChatContent.File(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
