                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileChatContent) = when(value) {
        is MobileChatContent.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is MobileChatContent.InlineImage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`blobIdHex`)
                + FfiConverterString.allocationSize(value.`filename`)
                + FfiConverterULong.allocationSize(value.`totalSize`)
                + FfiConverterOptionalByteArray.allocationSize(value.`bytes`)
                + FfiConverterTypeMobileBlobTransferState.allocationSize(value.`state`)
            )
        }
        is MobileChatContent.File -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`blobIdHex`)
                + FfiConverterString.allocationSize(value.`filename`)
                + FfiConverterULong.allocationSize(value.`totalSize`)
                + FfiConverterTypeMobileBlobTransferState.allocationSize(value.`state`)
            )
        }
    }

    override fun write(value: MobileChatContent, buf: ByteBuffer) {
        when(value) {
            is MobileChatContent.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is MobileChatContent.InlineImage -> {
                buf.putInt(2)
                FfiConverterString.write(value.`blobIdHex`, buf)
                FfiConverterString.write(value.`filename`, buf)
                FfiConverterULong.write(value.`totalSize`, buf)
                FfiConverterOptionalByteArray.write(value.`bytes`, buf)
                FfiConverterTypeMobileBlobTransferState.write(value.`state`, buf)
                Unit
            }
            is MobileChatContent.File -> {
                buf.putInt(3)
                FfiConverterString.write(value.`blobIdHex`, buf)
                FfiConverterString.write(value.`filename`, buf)
                FfiConverterULong.write(value.`totalSize`, buf)
                FfiConverterTypeMobileBlobTransferState.write(value.`state`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







sealed class MobileCoreException(message: String): kotlin.Exception(message) {
        
        class InvalidArgument(message: String) : MobileCoreException(message)
        
        class AudioInitFailed(message: String) : MobileCoreException(message)
        
        class Internal(message: String) : MobileCoreException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileCoreException = FfiConverterTypeMobileCoreError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileCoreError : FfiConverterRustBuffer<MobileCoreException> {
    override fun read(buf: ByteBuffer): MobileCoreException {
        
            return when(buf.getInt()) {
            1 -> MobileCoreException.InvalidArgument(FfiConverterString.read(buf))
            2 -> MobileCoreException.AudioInitFailed(FfiConverterString.read(buf))
            3 -> MobileCoreException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: MobileCoreException): ULong {
        return 4UL
    }

    override fun write(value: MobileCoreException, buf: ByteBuffer) {
        when(value) {
            is MobileCoreException.InvalidArgument -> {
                buf.putInt(1)
                Unit
            }
            is MobileCoreException.AudioInitFailed -> {
                buf.putInt(2)
                Unit
            }
            is MobileCoreException.Internal -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





public interface MobileEventListener {
    
    fun `onJoinedRoom`(`localPeerId`: kotlin.UShort, `inviteUri`: kotlin.String, `isLanLocked`: kotlin.Boolean)
    
    fun `onLanAuthFailed`(`message`: kotlin.String)
    
    fun `onLeftRoom`()
    
    fun `onPeersUpdated`(`peers`: List<MobilePeerSnapshot>)
    
    fun `onChatItemReceived`(`item`: MobileChatItem)
    
    fun `onBlobStateChanged`(`blobIdHex`: kotlin.String, `state`: MobileBlobTransferState, `inlineBytes`: kotlin.ByteArray?)
    
    fun `onPeerAvatarLoaded`(`clientUuidHex`: kotlin.String, `avatarHashHex`: kotlin.String, `rgba128`: kotlin.ByteArray)
    
    fun `onRemoteStreamUpdated`(`peerId`: kotlin.UShort, `stream`: MobileRemoteStreamInfo?)
    
    fun `onLanRoomsUpdated`(`rooms`: List<MobileLanRoomItem>)
    
    fun `onFriendsStatusUpdated`(`friends`: List<MobileFriendItem>)
    
    fun `onIncomingFriendCall`(`call`: MobileIncomingCall)
    
    fun `onShortCodeGenerated`(`code`: kotlin.String, `expiresInSecs`: kotlin.UShort)
    
    fun `onShortCodeCleared`()
    
    fun `onFriendInviteSent`(`pubKeyHex`: kotlin.String)
    
    fun `onError`(`message`: kotlin.String)
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

